import{af as t,ad as o,z as i,J as n,ab as a,x as s}from"./chunks/framework.D-2fLa7v.js";const P=JSON.parse('{"title":"Pro","description":"","frontmatter":{"aside":true},"headers":[],"relativePath":"devices/pro/index.md","filePath":"devices/pro/index.md"}'),d={name:"devices/pro/index.md"};function h(c,e,l,p,g,u){const r=o("DeviceCapabilities");return i(),n("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794239218000"},[e[0]||(e[0]=a('<h1 id="pro" tabindex="-1">Pro <a class="header-anchor" href="#pro" aria-label="Permalink to &quot;Pro&quot;">​</a></h1><p>The current Pro is Pro3 (PR3), a different hardware generation from <a href="/docs/pr/40/devices/history/PR2">ProN (PR2)</a>. The two generations share the same external appearance, so use the product code and hardware revision to identify your device before following its instructions. ProN (PR2) is now a legacy model and is no longer in production.</p><h2 id="capabilities" tabindex="-1">Feature guides <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Feature guides {#capabilities}&quot;">​</a></h2>',3)),s(r,{device:"PR3"}),e[1]||(e[1]=a('<p>Pro3 does not have the separate <a href="/docs/pr/40/devices/capabilities/gps-gsm-status-leds">GPS and GSM status LEDs</a> used by the older ProN/PR2. Use the product code and revision, not the enclosure appearance, to choose the matching documentation.</p><h2 id="images" tabindex="-1">Images <a class="header-anchor" href="#images" aria-label="Permalink to &quot;Images&quot;">​</a></h2><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/product-front/LB-DEV-PR2.png" alt="Pro3 tracker enclosure" tabindex="0"><figcaption>Pro3 tracker enclosure</figcaption></figure><p>The enclosure image is shared with ProN/PR2. It does not identify the internal electronics or LED layout.</p><h2 id="hardware-generations" tabindex="-1">Hardware generations <a class="header-anchor" href="#hardware-generations" aria-label="Permalink to &quot;Hardware generations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Generation</th><th>LED layout</th><th>Documentation</th></tr></thead><tbody><tr><td>Pro3 / PR3 (current)</td><td>Four orange indicators on revisions 02–04</td><td>This page</td></tr><tr><td>ProN / PR2 (legacy)</td><td>Four battery indicators plus two diagnostic indicators</td><td><a href="/docs/pr/40/devices/history/PR2">PR2 archive</a></td></tr></tbody></table><p>This is a generation guide, not a complete Pro3 specification. Cellular bands, wireless features, charging limits and certifications must be checked for the supplied Pro3 revision. The <a href="/docs/pr/40/devices/history/PR2">PR2 specification download</a> applies to PR2 only.</p><h2 id="led-indicators" tabindex="-1">LED indicators <a class="header-anchor" href="#led-indicators" aria-label="Permalink to &quot;LED indicators&quot;">​</a></h2><p>The <a href="/docs/pr/40/devices/capabilities/four-power-leds">four power LED capability</a> defines the normal battery and charging patterns. On revisions 02–04 these indicators are orange. They are also used during startup and for alerts, so four lit indicators are not always a battery reading.</p><p>There is no separate GPS/mobile-network colour table on Pro3. The older <a href="/docs/pr/40/devices/history/PR2#two-red-lights-and-four-orange-lights-after-a-restart">PR2 example of two red and four orange lights</a> is not this model’s layout. Use the <a href="/docs/pr/40/guides/leds">LED guide</a> for the first checks when a pattern is unfamiliar.</p><h3 id="charger-protection" tabindex="-1">Charger protection <a class="header-anchor" href="#charger-protection" aria-label="Permalink to &quot;Charger protection&quot;">​</a></h3><p>The charger can trigger a protection pattern that differs from the normal charging blink. If two lights keep flashing together or charging does not progress, contact <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">support</a> with a video and details of the charging accessory. Do not treat every flashing pattern as a battery reading.</p><h2 id="charging" tabindex="-1">Charging <a class="header-anchor" href="#charging" aria-label="Permalink to &quot;Charging&quot;">​</a></h2><p>Use the charging accessory and power supply specified for your Pro3 revision. Do not apply PR2 voltage/current ratings or charging-time instructions to Pro3.</p><p>See <a href="/docs/pr/40/devices/capabilities/four-power-leds#charging">four power LED charging patterns</a> for the normal blinking and steady states. A steady high-charge display is not an exact 100% reading.</p><h2 id="pro-pr2" tabindex="-1">Earlier Pro generations <a class="header-anchor" href="#pro-pr2" aria-label="Permalink to &quot;Earlier Pro generations {#pro-pr2}&quot;">​</a></h2><p>The <a href="/docs/pr/40/devices/history/PR2">ProN/PR2 archive</a> contains its specifications, images and diagnostic-light information. PR2 is no longer in production.</p><h2 id="get-help" tabindex="-1">Get help <a class="header-anchor" href="#get-help" aria-label="Permalink to &quot;Get help&quot;">​</a></h2><p>For specifications or troubleshooting, <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">contact support</a> with the product code, device ID and hardware revision if known. Include whether the device is charging and a short video if you are asking about a repeating light pattern.</p>',19))])}const b=t(d,[["render",h]]);export{P as __pageData,b as default};
